export interface CredentialRecord { userId: string; displayName: string; email: string; avatarKey: string; password: string; }
export interface AuthenticatedProfile { userId: string; displayName: string; email: string; avatarKey: string; }
function emailValid(email: string): boolean { const parts = email.split('@'); return parts.length === 2 && !!parts[0] && !!parts[1]; }
export function authenticateLocal(records: readonly CredentialRecord[], email: string, password: string): AuthenticatedProfile {
  const seen = new Set<string>();
  let match: CredentialRecord | undefined;
  for (const source of records) {
    const r = { ...source };
    if ([r.userId, r.displayName, r.email, r.avatarKey, r.password].some(x => !x.trim()) || !emailValid(r.email)) throw new Error('Invalid credential record');
    const key = r.email.toLowerCase();
    if (seen.has(key)) throw new Error('Duplicate email');
    seen.add(key);
    if (r.email === email) match = r;
  }
  if (!email.trim() || !password || !match || match.password !== password) throw new Error('Authentication failed');
  return { userId: match.userId, displayName: match.displayName, email: match.email, avatarKey: match.avatarKey };
}

