import { authenticateLocal, CredentialRecord } from './solution';

function assert(value: boolean, message: string): void { if (!value) throw new Error(message); }
function equal(actual: unknown, expected: unknown, message: string): void { if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`); }
function deepEqual(actual: unknown, expected: unknown, message: string): void { if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: ${JSON.stringify(actual)}`); }
function throws(action: () => unknown, message: string): Error { try { action(); } catch (error) { return error instanceof Error ? error : new Error(String(error)); } throw new Error(message); }
function authenticationFails(action: () => unknown, message: string): void { equal(throws(action, message).message, 'Authentication failed', message); }

const records: CredentialRecord[] = [
  { userId: 'u1', displayName: 'Ada', email: 'Ada@Example.com', avatarKey: 'ada.png', password: 'CaseSensitive' },
  { userId: 'u2', displayName: 'Grace', email: 'grace@example.com', avatarKey: 'grace.png', password: 'secret' }
];
const before = JSON.stringify(records);
const profile = authenticateLocal(records, 'ADA@example.COM', 'CaseSensitive');
deepEqual(profile, { userId: 'u1', displayName: 'Ada', email: 'Ada@Example.com', avatarKey: 'ada.png' }, 'successful authentication omits password');
assert(!('password' in profile), 'password is not exposed');
equal(JSON.stringify(records), before, 'records are not mutated');
(profile as { displayName: string }).displayName = 'corrupt';
equal(authenticateLocal(records, 'ada@example.com', 'CaseSensitive').displayName, 'Ada', 'returned profile is independent');

authenticationFails(() => authenticateLocal(records, '', 'CaseSensitive'), 'blank email fails');
authenticationFails(() => authenticateLocal(records, '   ', 'CaseSensitive'), 'whitespace email fails');
authenticationFails(() => authenticateLocal(records, 'ada@example.com', ''), 'blank password fails');
authenticationFails(() => authenticateLocal(records, 'ada@example.com', '   '), 'whitespace password fails');
authenticationFails(() => authenticateLocal(records, 'unknown@example.com', 'CaseSensitive'), 'unknown email fails');
authenticationFails(() => authenticateLocal(records, 'ada@example.com', 'casesensitive'), 'password comparison is exact');
authenticationFails(() => authenticateLocal([], 'a@b', 'x'), 'empty record list cannot authenticate');

throws(() => authenticateLocal([
  { userId: '', displayName: 'A', email: 'a@b', avatarKey: 'x', password: 'p' }
], 'a@b', 'p'), 'blank stored field rejected');
throws(() => authenticateLocal([
  { userId: 'u', displayName: 'A', email: 'ab', avatarKey: 'x', password: 'p' }
], 'ab', 'p'), 'stored email without at-sign rejected');
throws(() => authenticateLocal([
  { userId: 'u', displayName: 'A', email: '@b', avatarKey: 'x', password: 'p' }
], '@b', 'p'), 'stored email missing left side rejected');
throws(() => authenticateLocal([
  { userId: 'u', displayName: 'A', email: 'a@', avatarKey: 'x', password: 'p' }
], 'a@', 'p'), 'stored email missing right side rejected');
throws(() => authenticateLocal([
  { userId: 'u', displayName: 'A', email: 'a@b@c', avatarKey: 'x', password: 'p' }
], 'a@b@c', 'p'), 'stored email with multiple at-signs rejected');
throws(() => authenticateLocal([
  { userId: 'u1', displayName: 'A', email: 'same@example.com', avatarKey: 'x', password: 'p1' },
  { userId: 'u2', displayName: 'B', email: 'SAME@EXAMPLE.COM', avatarKey: 'y', password: 'p2' }
], 'same@example.com', 'p1'), 'case-insensitive duplicate stored emails rejected');
throws(() => authenticateLocal([
  records[0],
  { userId: ' ', displayName: 'Bad', email: 'bad@example.com', avatarKey: 'x', password: 'p' }
], 'ada@example.com', 'CaseSensitive'), 'all stored records validated before authentication');

